package org.brightstats.data;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.time.Instant;
import java.util.*;
import com.google.gson.*;
import org.brightstats.model.*;

/** Local project catalog. Removing an entry never deletes its project file. */
public final class WorkspaceStore {
    public static final String FILE="bright-stats-workspace.json";
    public static final long MAX_PROJECT_BYTES=64L*1024*1024;
    private static final Gson JSON=new GsonBuilder().serializeNulls().setPrettyPrinting().setStrictness(Strictness.STRICT).create();
    public record Project(String id,String name,String createdUtc,String modifiedUtc){
        public Project{if(id==null||!id.matches("[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}"))throw new IllegalArgumentException("Invalid workspace project identity.");name=label(name);Instant.parse(createdUtc);Instant.parse(modifiedUtc);}
    }
    public record Manifest(String format,int version,List<Project> projects,String active){
        public Manifest{if(!"bright-stats-workspace".equals(format)||version!=1)throw new IllegalArgumentException("Unsupported workspace format/version.");projects=List.copyOf(projects);active=active==null?"":active;if(projects.size()>1000)throw new IllegalArgumentException("A workspace supports at most 1,000 projects.");Set<String> ids=new HashSet<>(),names=new HashSet<>();for(var project:projects)if(!ids.add(project.id())||!names.add(project.name().toLowerCase(Locale.ROOT)))throw new IllegalArgumentException("Workspace project identities and names must be unique.");if(!active.isEmpty()&&!ids.contains(active))throw new IllegalArgumentException("Workspace active project is missing.");}
    }
    private final Path root;
    private Manifest manifest;
    private WorkspaceStore(Path root,Manifest manifest)throws IOException{this.root=root.toRealPath();this.manifest=manifest;}
    public Path root(){return root;}public Manifest manifest(){return manifest;}
    public static WorkspaceStore create(Path directory)throws IOException{Files.createDirectories(directory);Path root=directory.toRealPath();if(Files.exists(root.resolve(FILE),LinkOption.NOFOLLOW_LINKS))throw new FileAlreadyExistsException("Workspace already exists; open it instead.");var store=new WorkspaceStore(root,new Manifest("bright-stats-workspace",1,List.of(),""));store.directory("projects");store.writeManifest(store.manifest);return store;}
    public static WorkspaceStore open(Path directory)throws IOException{Path root=directory.toRealPath(),file=root.resolve(FILE);if(Files.isSymbolicLink(file)||!Files.isRegularFile(file,LinkOption.NOFOLLOW_LINKS)||Files.size(file)>2*1024*1024)throw new IllegalArgumentException("Choose a regular bounded workspace manifest.");var manifest=JSON.fromJson(BoundedJson.read(file),Manifest.class);var store=new WorkspaceStore(root,manifest);for(var project:manifest.projects())store.path(project.id());return store;}
    private static String label(String value){if(value==null)throw new IllegalArgumentException("Name the project.");String name=java.text.Normalizer.normalize(value.strip(),java.text.Normalizer.Form.NFC);if(name.isBlank()||name.length()>120||name.codePoints().anyMatch(Character::isISOControl))throw new IllegalArgumentException("Use a project name of 1-120 visible characters.");return name;}
    private Path checked(Path value)throws IOException{Path target=value.toAbsolutePath().normalize();if(!target.startsWith(root))throw new IllegalArgumentException("Workspace path escapes its root.");Path ancestor=Files.exists(target,LinkOption.NOFOLLOW_LINKS)?target:target.getParent();while(!Files.exists(ancestor,LinkOption.NOFOLLOW_LINKS))ancestor=ancestor.getParent();if(Files.isSymbolicLink(target)||!ancestor.toRealPath().startsWith(root))throw new IllegalArgumentException("Workspace paths cannot follow links outside their root.");return target;}
    private Path directory(String relative)throws IOException{Path directory=checked(root.resolve(relative));Files.createDirectories(directory);return checked(directory);}
    public Path path(String id)throws IOException{project(id);return checked(root.resolve("projects").resolve(id+".json"));}
    public Project project(String id){return manifest.projects().stream().filter(project->project.id().equals(id)).findFirst().orElseThrow(()->new IllegalArgumentException("Workspace project is missing."));}
    public JsonObject read(String id)throws IOException{Path file=path(id);if(!Files.isRegularFile(file,LinkOption.NOFOLLOW_LINKS)||Files.size(file)>MAX_PROJECT_BYTES)throw new IllegalArgumentException("Project is missing, linked or larger than 64 MiB.");var value=BoundedJson.read(file).getAsJsonObject();validate(value);return value;}
    public Project add(String name,JsonObject document)throws IOException{validate(document);String now=Instant.now().toString();var project=new Project(UUID.randomUUID().toString(),name,now,now);List<Project> projects=new ArrayList<>(manifest.projects());projects.add(project);var next=new Manifest("bright-stats-workspace",1,projects,project.id());Path target=checked(directory("projects").resolve(project.id()+".json"));write(target,document);try{writeManifest(next);}catch(IOException|RuntimeException failure){Files.deleteIfExists(checked(target));throw failure;}return project;}
    public void save(String id,JsonObject document)throws IOException{validate(document);Project old=project(id);Path target=path(id);if(Files.exists(target,LinkOption.NOFOLLOW_LINKS)){Path history=directory("history/"+id);Path backup=checked(history.resolve(Instant.now().toEpochMilli()+"-"+UUID.randomUUID()+".json"));Files.copy(target,backup);}write(target,document);List<Project> projects=new ArrayList<>(manifest.projects());projects.set(projects.indexOf(old),new Project(old.id(),old.name(),old.createdUtc(),Instant.now().toString()));writeManifest(new Manifest("bright-stats-workspace",1,projects,id));}
    public void activate(String id)throws IOException{project(id);writeManifest(new Manifest("bright-stats-workspace",1,manifest.projects(),id));}
    public void rename(String id,String name)throws IOException{Project old=project(id);List<Project> projects=new ArrayList<>(manifest.projects());projects.set(projects.indexOf(old),new Project(id,name,old.createdUtc(),Instant.now().toString()));writeManifest(new Manifest("bright-stats-workspace",1,projects,manifest.active()));}
    public Project duplicate(String id,String name)throws IOException{return add(name,read(id));}
    public void remove(String id)throws IOException{project(id);var projects=manifest.projects().stream().filter(project->!project.id().equals(id)).toList();writeManifest(new Manifest("bright-stats-workspace",1,projects,manifest.active().equals(id)?"":manifest.active()));}
    private void writeManifest(Manifest next)throws IOException{write(checked(root.resolve(FILE)),JSON.toJsonTree(next));manifest=next;}
    private void write(Path file,JsonElement value)throws IOException{Path target=checked(file);byte[] bytes=JSON.toJson(value).getBytes(StandardCharsets.UTF_8);if(bytes.length>MAX_PROJECT_BYTES)throw new IllegalArgumentException("Workspace project exceeds 64 MiB.");Path temporary=Files.createTempFile(checked(target.getParent()),".bright-stats-", ".tmp");try{Files.write(temporary,bytes,StandardOpenOption.TRUNCATE_EXISTING);checked(target);try{Files.move(temporary,target,StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}catch(AtomicMoveNotSupportedException unsupported){Files.move(temporary,target,StandardCopyOption.REPLACE_EXISTING);}}finally{Files.deleteIfExists(temporary);}}
    public static JsonObject emptyProject(){JsonObject object=new JsonObject();object.addProperty("format","bright-stats-project");object.addProperty("formatVersion",1);for(String key:List.of("columnNames","observations","blocks","edges"))object.add(key,new JsonArray());return object;}
    public static void validate(JsonObject document){
        if(document.has("format")&&!document.get("format").getAsString().equals("bright-stats-project")||document.has("formatVersion")&&document.get("formatVersion").getAsBigDecimal().intValueExact()!=1)throw new IllegalArgumentException("Choose a Bright-Stats project.");for(String field:List.of("observations","columnNames","blocks","edges"))if(!document.has(field)||!document.get(field).isJsonArray())throw new IllegalArgumentException("Project is missing "+field+".");var rows=document.getAsJsonArray("observations");var columns=document.getAsJsonArray("columnNames");if(columns.size()>10000||(long)rows.size()*columns.size()>5000000L)throw new IllegalArgumentException("Project exceeds five million cells or 10,000 columns.");if(!rows.isEmpty()&&columns.isEmpty())throw new IllegalArgumentException("Nonempty numeric projects need at least one column.");Set<String> names=new HashSet<>();for(var value:columns)if(!value.isJsonPrimitive()||!value.getAsJsonPrimitive().isString()||value.getAsString().isBlank()||!names.add(value.getAsString()))throw new IllegalArgumentException("Project column names must be unique nonempty text.");for(var row:rows){if(!row.isJsonArray()||row.getAsJsonArray().size()!=columns.size())throw new IllegalArgumentException("Project rows must match its columns.");for(var value:row.getAsJsonArray())if(!value.isJsonPrimitive()||!value.getAsJsonPrimitive().isNumber()||!Double.isFinite(value.getAsDouble()))throw new IllegalArgumentException("Prepare missing/nonfinite values before saving a numeric project.");}if(rows.isEmpty()&&(!columns.isEmpty()||!document.getAsJsonArray("blocks").isEmpty()||!document.getAsJsonArray("edges").isEmpty()))throw new IllegalArgumentException("An empty project cannot contain a bound data/model layout.");DiagramClipboard.validate(document,columns.size());if(document.has("modelLibrary"))ModelLibrary.read(document.get("modelLibrary"));if(document.has("typedModels"))for(var entry:document.getAsJsonObject("typedModels").entrySet()){var family=ElementType.Family.valueOf(entry.getKey());if(TypedDiagram.parse(entry.getValue().toString()).family()!=family)throw new IllegalArgumentException("Typed model family differs from its project key.");}}
}
